import json
from src.nodes.base import BaseNode
from src.runtime import mcp_runtime

class MCPServerInitNode(BaseNode):
    name = "MCP: Server Init"
    category = "MCP"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("server_name", "string", widget_type="text", default="default")
        self.add_input("transport_type", "string", widget_type="dropdown", options=["stdio", "sse"], default="stdio")
        self.add_input("command", "string", widget_type="text", default="")
        self.add_input("args", "string", widget_type="text", default="")
        self.add_input("env_json", "string", widget_type="text", default="")
        self.add_input("url", "string", widget_type="text", default="")
        self.add_output("connected", "bool")
        self.add_output("server_info", "any")
        self.add_output("capabilities", "any")
        self.add_output("server_name", "string")
        # [AUTO-GENERATED-PORTS-END]

    @staticmethod
    def _parse_args(raw):
        if not raw:
            return []
        raw = raw.strip()
        if not raw:
            return []
        if raw.startswith("["):
            try:
                value = json.loads(raw)
                if isinstance(value, list):
                    return [str(item) for item in value]
            except json.JSONDecodeError:
                pass
        return [piece.strip() for piece in raw.split(",") if piece.strip()]

    @staticmethod
    def _parse_env(raw):
        if not raw:
            return None
        raw = raw.strip()
        if not raw:
            return None
        try:
            value = json.loads(raw)
            return value if isinstance(value, dict) else None
        except json.JSONDecodeError:
            return None

    async def execute(self, inputs):
        server_name = (inputs.get("server_name") or "default").strip() or "default"
        transport = (inputs.get("transport_type") or "stdio").strip().lower()
        if transport not in ("stdio", "sse"):
            self.log_error(f"Unsupported transport: {transport!r}")
            return {"connected": False, "server_info": {}, "capabilities": {}, "server_name": server_name, "exec_out": True}

        if transport == "stdio":
            command = (inputs.get("command") or "").strip()
            if not command:
                self.log_error("stdio transport requires a 'command' value (e.g. npx, python).")
                return {"connected": False, "server_info": {}, "capabilities": {}, "server_name": server_name, "exec_out": True}
            config = {
                "command": command,
                "args": self._parse_args(inputs.get("args") or ""),
                "env": self._parse_env(inputs.get("env_json") or ""),
            }
        else:
            url = (inputs.get("url") or "").strip()
            if not url:
                self.log_error("sse transport requires a 'url' value.")
                return {"connected": False, "server_info": {}, "capabilities": {}, "server_name": server_name, "exec_out": True}
            config = {"url": url, "headers": None}

        try:
            result = await mcp_runtime.register_server(server_name, transport, config)
            reused = result.get("reused", False)
            if reused:
                self.log_info(f"Reusing existing MCP session '{server_name}'.")
            else:
                self.log_success(f"MCP session '{server_name}' connected ({transport}).")
            return {
                "connected": bool(result.get("connected")),
                "server_info": result.get("server_info") or {},
                "capabilities": result.get("capabilities") or {},
                "server_name": server_name,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"MCP register_server failed: {exc}")
            return {"connected": False, "server_info": {}, "capabilities": {}, "server_name": server_name, "exec_out": True}

def register_node():
    return MCPServerInitNode
